// McpServerUpdate Request to update mutable fields on an existing MCP server.
//
// Stays flat (no discriminated union) because PATCH bodies arrive without
// the client necessarily knowing the row's runtime_kind. The service
// layer enforces per-runtime-kind shape after loading the row:
// container_image rows reject “endpoint_url“, managed_remote rows
// reject every container-only field.
//
// “runtime_kind“ and “transport“ are intentionally absent — changing
// either requires delete-and-recreate so the reconciler doesn't need to
// re-plan pod primitives mid-flight.
type McpServerUpdate struct {
	// AcknowledgedCredentialHost Destination the caller accepts will receive this server's Runtime Vault secrets. Required when re-pointing ``endpoint_url`` at a different authority on a managed-remote row that has ``secret_headers``; must equal the authority of the new ``endpoint_url`` — its host, plus ``:port`` when the port is not the scheme default. Changing only the path on the same authority needs nothing — the secret already goes there; changing the port does need it, because a different port can be a separately operated listener. Naming the destination rather than sending a bare flag is deliberate: it proves the caller knew *where* the secret was going, and a destination changed after the confirmation was shown no longer matches. Recorded to the audit trail.
	AcknowledgedCredentialHost *string `json:"acknowledged_credential_host"`

	// Args Argv-style arguments appended to command. Container-image rows only.
	Args *[]string `json:"args"`

	// Command Argv-style entrypoint override. Container-image rows only.
	Command *[]string `json:"command"`

	// CredentialSidecarImage Per-server credential sidecar image override. Send null to inherit the provisioner default. Container-image rows only.
	CredentialSidecarImage *string `json:"credential_sidecar_image"`

	// Description Free-form description
	Description *string `json:"description"`

	// EndpointUrl Managed-remote URL. Managed-remote rows only.
	EndpointUrl *string `json:"endpoint_url"`

	// EnvPlaintext Non-sensitive environment variables (full replacement). Container-image rows only.
	EnvPlaintext *map[string]string `json:"env_plaintext"`

	// EnvSecretRefs Env-var name → secret_key_path (full replacement). Container-image rows only.
	EnvSecretRefs *map[string]string `json:"env_secret_refs"`

	// Image Container image reference. Container-image rows only.
	Image *string `json:"image"`

	// IntegrationCredentialIds Integration connections this server is linked to (full replacement). Sending a list that omits a currently-linked connection unlinks it. Container-image rows only.
	IntegrationCredentialIds *[]string `json:"integration_credential_ids"`

	// Name Human-readable label (unique per org)
	Name *string `json:"name"`

	// PodHostMode How Botyard sets the HTTP ``Host`` when connecting to an in-cluster MCP pod.
	//
	// This is a fixed property of the server's HTTP framework, declared as
	// configuration (like ``port``) rather than discovered at runtime:
	//
	// * ``natural`` — send the pod's in-cluster Service FQDN as ``Host`` (httpx's
	//   default). Correct for the MCP Python SDK / uvx, Node/npx, and every
	//   first-party ``ghcr.io/botyard-ai/*`` wrapper image. The default.
	// * ``pod_localhost`` — send ``Host: localhost:<port>``. Required by servers
	//   that enforce DNS-rebinding host allowlists (``mark3labs/mcp-go``, e.g.
	//   ``grafana/mcp-grafana``), which reject the Service FQDN with
	//   ``403 forbidden: host not allowed``. Sending it to a server that does not
	//   want it (Python SDK) instead breaks the handshake with ``Session
	//   terminated`` (the server's ``307`` echoes the forged Host back to the
	//   client's own localhost).
	//
	// Only meaningful for ``runtime_kind=container_image``; ignored for
	// ``managed_remote`` (the vendor host is always preserved).
	PodHostMode *McpPodHostMode `json:"pod_host_mode,omitempty"`

	// Port Container port for the streamable-http transport. Container-image rows only.
	Port *int `json:"port"`

	// RequestTimeoutSeconds Per-server gateway request-timeout override (seconds). Send an explicit null to clear it and inherit the gateway default. Applies to both runtime kinds.
	RequestTimeoutSeconds *int `json:"request_timeout_seconds"`

	// SecretFileMounts Absolute container file path → secret_key_path mounted as read-only files (full replacement). Container-image rows only.
	SecretFileMounts *map[string]string `json:"secret_file_mounts"`

	// SecretHeaderSchemes Header name to the scheme composing its outbound value from the resolved vault secret (full replacement; send {} to clear and send every header verbatim). Every name must appear in the resulting ``secret_headers``. Managed-remote rows only.
	SecretHeaderSchemes *map[string]McpServerUpdate_SecretHeaderSchemes_AdditionalProperties `json:"secret_header_schemes,omitempty"`

	// SecretHeaders Header name to Runtime Vault key path (full replacement; send {} to clear). Managed-remote rows only.
	SecretHeaders *map[string]string `json:"secret_headers,omitempty"`

	// Slug URL-safe identifier (unique per org among non-deleted servers)
	Slug *string `json:"slug"`

	// StaticHeaders Non-sensitive outbound headers (full replacement; send {} to clear). Managed-remote rows only.
	StaticHeaders *map[string]string `json:"static_headers,omitempty"`
}

